class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def getIntersectionNode(self, headA: ListNode, headB: ListNode) -> ListNode:
    seen = set()
    a = headA
    while a is not None:
        seen.add(a)
        a = a.next
    b = headB
    while b is not None:
        if b in seen:
            return b
        b = b.next
    return None

